"""
title: Image Response Fixer
description: Detects when Gemma emits a malformed fake tool-call instead of the image markdown tag, and replaces it with the actual generated image
"""

import re
from pydantic import BaseModel


def extract_text(content):
    """Handle both plain-string and structured list content formats."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for block in content:
            if isinstance(block, dict) and block.get("type") == "text":
                parts.append(block.get("text", ""))
        return "\n".join(parts)
    return ""


class Filter:
    class Valves(BaseModel):
        pass

    def __init__(self):
        self.valves = self.Valves()

    def outlet(self, body: dict, __user__: dict = None) -> dict:
        messages = body.get("messages", [])
        if not messages:
            return body

        last = messages[-1]
        if last.get("role") != "assistant":
            return body

        content_text = extract_text(last.get("content", ""))

        # DEBUG marker - remove once confirmed working
        debug_prefix = "[FILTER RAN] "

        looks_malformed = (
            '"action"' in content_text
            and '"action_input"' in content_text
            and "generate_image" in content_text
            and "![" not in content_text
        )

        if not looks_malformed:
            # Still mark that the filter executed, even if it didn't need to fix anything
            if isinstance(last.get("content"), str):
                last["content"] = debug_prefix + "(no fix needed) " + last["content"]
            return body

        image_markdown = None
        for msg in reversed(messages[:-1]):
            msg_text = extract_text(msg.get("content", ""))
            match = re.search(r"!\[.*?\]\(https?://[^\s)]+\)", msg_text)
            if match:
                image_markdown = match.group(0)
                break

        if image_markdown:
            last["content"] = (
                f"{debug_prefix}Here's your generated image:\n\n{image_markdown}"
            )
        else:
            last["content"] = (
                debug_prefix
                + "(malformed detected, but no image URL found in history) "
                + content_text
            )

        return body
